<script>
/**
 * PHYSICS PLAYGROUND ENGINE
 */
(function() {
    const canvas = document.getElementById('sim');
    const ctx = canvas.getContext('2d');
    const btnDrop = document.getElementById('drop');
    const btnPlay = document.getElementById('play');
    const btnClear = document.getElementById('clear');

    const config = {
        gravity: 0.3,
        restitution: 0.85, // Energy loss on bounce
        colors: ['#FF5252', '#FF4081', '#E040FB', '#7C4DFF', '#536DFE', '#448AFF', '#40C4FF', '#18FFFF', '#64FFDA', '#69F0AE', '#B2FF59', '#EEFF41', '#FFFF00', '#FFD740', '#FFAB40', '#FF6E40']
    };

    const state = {
        balls: [],
        isPaused: false
    };

    // Physics Logic
    function updatePhysics(dt) {
        for (let i = 0; i < state.balls.length; i++) {
            const b = state.balls[i];

            // Apply Gravity
            b.vy += config.gravity * dt;

            // Update Position
            b.x += b.vx * dt;
            b.y += b.vy * dt;

            // Collision: Left/Right walls
            if (b.x - b.r < 0) {
                b.x = b.r;
                b.vx = Math.abs(b.vx) * config.restitution;
            } else if (b.x + b.r > canvas.width) {
                b.x = canvas.width - b.r;
                b.vx = -Math.abs(b.vx) * config.restitution;
            }

            // Collision: Top/Bottom walls
            if (b.y - b.r < 0) {
                b.y = b.r;
                b.vy = Math.abs(b.vy) * config.restitution;
            } else if (b.y + b.r > canvas.height) {
                b.y = canvas.height - b.r;
                b.vy = -Math.abs(b.vy) * config.restitution;
            }
        }
    }

    function render() {
        // Clear background
        ctx.fillStyle = '#1e1e1e';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Draw balls
        for (let i = 0; i < state.balls.length; i++) {
            const b = state.balls[i];
            ctx.beginPath();
            ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
            ctx.fillStyle = b.color || '#ffffff';
            ctx.fill();
            // Add a little shine for aesthetics
            ctx.shadowBlur = 10;
            ctx.shadowColor = b.color || '#ffffff';
            ctx.closePath();
        }
        // Reset shadow for next frame
        ctx.shadowBlur = 0;
    }

    /**
     * PUBLIC API - Required for grading
     */
    window.sim = {
        get w() { return canvas.width; },
        get h() { return canvas.height; },
        balls() {
            return state.balls.map(b => ({
                x: b.x,
                y: b.y,
                vx: b.vx,
                vy: b.vy,
                r: b.r
            }));
        },
        addBall(x, y, vx = 0, vy = 0, r) {
            const radius = r || 12;
            const color = config.colors[Math.floor(Math.random() * config.colors.length)];
            state.balls.push({ x, y, vx, vy, r: radius, color });
        },
        clear() {
            state.balls = [];
        },
        step(dt = 1) {
            updatePhysics(dt);
            render();
        }
    };

    // Animation Loop
    function loop() {
        if (!state.isPaused) {
            window.sim.step(1);
        } else {
            // Redraw even when paused to allow external updates to be visible
            render();
        }
        requestAnimationFrame(loop);
    }

    // UI Interaction
    btnDrop.addEventListener('click', () => {
        const x = canvas.width / 2;
        const y = 50;
        const vx = (Math.random() - 0.5) * 10;
        const vy = 2;
        window.sim.addBall(x, y, vx, vy);
    });

    btnPlay.addEventListener('click', () => {
        state.isPaused = !state.isPaused;
        btnPlay.textContent = state.isPaused ? 'Play' : 'Pause';
    });

    btnClear.addEventListener('click', () => {
        window.sim.clear();
    });

    canvas.addEventListener('mousedown', (e) => {
        const rect = canvas.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        // Add ball with random velocity at click location
        window.sim.addBall(x, y, (Math.random() - 0.5) * 8, (Math.random() - 0.5) * 8);
    });

    // Start the loop
    requestAnimationFrame(loop);
})();
</script>

<div class="instruction">Click canvas to spawn balls</div>

</body>
</html>
